#include "zip_read_fuzzer.cc"
#include <stdio.h>
#include <stdlib.h>

/* fuzz target entry point, works without libFuzzer */

int
main(int argc, char **argv) {
    FILE *f;
    char *buf = NULL;
    long siz_buf;

    if (argc < 2) {
        fprintf(stderr, "no input file\n");
        goto err;
    }

    f = fopen(argv[1], "rb");
    if (f == NULL) {
        fprintf(stderr, "error opening input file %s\n", argv[1]);
        goto err;
    }

    fseek(f, 0, SEEK_END);

    siz_buf = ftell(f);
    rewind(f);

    if (siz_buf < 1) {
        goto err;
    }

    buf = (char *)malloc(siz_buf);
    if (buf == NULL) {
        fprintf(stderr, "malloc() failed\n");
        goto err;
    }

    if (fread(buf, siz_buf, 1, f) != 1) {
        fprintf(stderr, "fread() failed\n");
        goto err;
    }

    (void)LLVMFuzzerTestOneInput((uint8_t *)buf, siz_buf);

err:
    free(buf);

    return 0;
}

#include <zip.h>

#ifdef __cplusplus
extern "C"
#endif
int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size)
{
    zip_source_t *src;
    zip_t *za;
    zip_error_t error;
    char buf[32768];
    zip_int64_t i, n;
    zip_file_t *f;

    zip_error_init(&error);

    if ((src = zip_source_buffer_create(data, size, 0, &error)) == NULL) {
        zip_error_fini(&error);
        return 0;
    }

    if ((za = zip_open_from_source(src, 0, &error)) == NULL) {
        zip_source_free(src);
        zip_error_fini(&error);
        return 0;
    }

    zip_error_fini(&error);

    n = zip_get_num_entries(za, 0);

    for (i = 0; i < n; i++) {
        f = zip_fopen_index(za, i, 0);
        if (f == NULL) {
            continue;
        }

        while (zip_fread(f, buf, sizeof(buf)) > 0) {
            ;
        }

        zip_fclose(f);
    }

    zip_close(za);

    return 0;
}
